entries[302918] = { ["name"] = "Zoatroiden beschwören", ["text"] = "Ca. 3 Procs pro Minute\nBeim Wirken einer Einzelzielheilung besteht die Chance, einen Zoatroiden auf Eurem Ziel zu beschwören, der [ 967 * (1 + Vielseitigkeit)] Schaden absorbiert und abhängig von der verbleibenden Absorption bis zu 65 Vielseitigkeit gewährt. Pro 10% Mana, die Ihr verbraucht, wird Euer Zoatroid genährt, was die Absorption um [ 97 * (1 + Vielseitigkeit)] und die Vielseitigkeit um 6 erhöht." }
