entries[302986] = { ["name"] = "Potenz des Genies", ["text"] = "Ca. 5 Procs pro Minute\nEure Zauber haben eine Chance, Euch eine Aufladung von 'Potenz' zu gewähren. Wenn Eure Gesundheit oder Euer Mana unter 10% fällt, wird 'Potenz' ausgelöst. Innerhalb von 40 Metern erleiden Gegner dadurch Schaden und Verbündete werden geheilt, jeweils in Höhe von [ 100 * (1 + Vielseitigkeit)] pro Aufladung." }
entries[302987] = { ["name"] = "Instabile Regeneration", ["text"] = "Wirken in 3 sek.\nReagenzien:\nInstabile Isotope (100)\nAbsorbiert 100 instabile Isotope, was die Bedrohungserzeugung um 20% sowie den erlittenen Naturschaden um 5% erhöht und den Zaubernden für 30 Min. regelmäßig um 1% bis 5% pro 6 Sek. heilt.\n\nKann nur in Mechagon genutzt werden." }
